python3 - <<'EOF'
# Check glibc source layout knowledge: dump _rtld_global_ro symbol info from system libc
import subprocess
out = subprocess.run(['nm','-D','--defined-only','/lib/x86_64-linux-gnu/libc.so.6'], capture_output=True, text=True).stdout
for line in out.splitlines():
    if '_rtld_global' in line:
        print(line)
out2 = subprocess.run(['readelf','-sW','/lib/x86_64-linux-gnu/libc.so.6'], capture_output=True, text=True).stdout
for line in out2.splitlines():
    if '_rtld_global_ro' in line:
        print(line)
EOF
